import 'package:flutter/material.dart';
import '../../services/api_service.dart';
class GroupsScreen extends StatefulWidget{const GroupsScreen({super.key});@override State<GroupsScreen> createState()=>_GroupsScreenState();}
class _GroupsScreenState extends State<GroupsScreen>{List groups=[],students=[],teachers=[],supervisors=[];List<String> subjects=[];bool loading=true;static const fallback=['العربية','اللغة الإنجليزية','الرياضيات','العلوم','الدراسات الاجتماعية','Math','Science','English','Arabic','German','French','Spanish','Quran'];List<dynamic> list(dynamic x){if(x is List)return List<dynamic>.from(x);if(x is Map){final d=x['data'];if(d is List)return List<dynamic>.from(d);if(d is Map&&d['data'] is List)return List<dynamic>.from(d['data']);}return [];}int id(dynamic x)=>int.tryParse('${x['id']}')??0;String sub(dynamic x)=>x is Map?'${x['subject']??x['name']??''}':'$x';void msg(Object e)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));@override void initState(){super.initState();load();}
Future<void> load()async{if(mounted)setState(()=>loading=true);Object? primaryError;try{final r=await ApiService.get('groups');if(mounted)setState(()=>groups=list(r));}catch(e){primaryError=e;}try{final r=await ApiService.get('students');if(mounted)setState(()=>students=list(r));}catch(_){ }try{final r=await ApiService.get('teachers');if(mounted)setState(()=>teachers=list(r));}catch(_){ }try{final r=await ApiService.get('subjects');final ss=list(r).map(sub).where((x)=>x.isNotEmpty).toSet().toList();if(mounted)setState(()=>subjects=ss.isEmpty?fallback:ss);}catch(_){if(mounted)setState(()=>subjects=fallback);}try{final r=await ApiService.get('supervisors');if(mounted)setState(()=>supervisors=list(r));}catch(_){ }if(mounted){setState(()=>loading=false);if(primaryError!=null)msg(primaryError!);}}
Future<void> form({dynamic item})async{if(teachers.isEmpty||students.isEmpty){msg(Exception(teachers.isEmpty?'أضف مدرسًا أولًا.':'أضف طلابًا أولًا.'));return;}int teacherId=id(item?['teacher']??{'id':item?['teacher_id']});String subject='${item?['subject']??subjects.first}';int? supervisorId=int.tryParse('${item?['supervisor_id']??''}');final name=TextEditingController(text:'${item?['name']??''}'),grade=TextEditingController(text:'${item?['grade']??''}'),rate=TextEditingController(text:'${item?['teacher_rate']??''}');final selected=<int>{...list(item?['students']).map(id)};final k=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(d)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:Text(item==null?'إنشاء مجموعة':'تعديل المجموعة'),content:SizedBox(width:520,child:SingleChildScrollView(child:Form(key:k,child:Column(children:[TextFormField(controller:name,decoration:const InputDecoration(labelText:'اسم المجموعة *'),validator:(v)=>v==null||v.trim().isEmpty?'مطلوب':null),TextFormField(controller:grade,decoration:const InputDecoration(labelText:'الصف')),DropdownButtonFormField<int>(value:teacherId,decoration:const InputDecoration(labelText:'المدرس *'),items:teachers.map((t)=>DropdownMenuItem(value:id(t),child:Text('${t['name']}'))).toList(),onChanged:(v){if(v!=null)set(()=>teacherId=v);}),DropdownButtonFormField<String>(value:subject,decoration:const InputDecoration(labelText:'المادة *'),items:subjects.map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v){if(v!=null)set(()=>subject=v);}),TextFormField(controller:rate,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'سعر الحصة *'),validator:(v)=>double.tryParse(v??'')==null?'أدخل السعر':null),if(supervisors.isNotEmpty)DropdownButtonFormField<int?>(value:supervisorId,decoration:const InputDecoration(labelText:'المشرف'),items:[const DropdownMenuItem<int?>(value:null,child:Text('بدون مشرف')),...supervisors.map((s)=>DropdownMenuItem<int?>(value:id(s),child:Text('${s['name']}')))],onChanged:(v)=>set(()=>supervisorId=v)),const SizedBox(height:8),...students.map((s){final sid=id(s);return CheckboxListTile(value:selected.contains(sid),title:Text('${s['name']}'),onChanged:(v)=>set((){if(v==true)selected.add(sid);else selected.remove(sid);});})])))),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:(){if(k.currentState!.validate()&&selected.isNotEmpty)Navigator.pop(d,true);},child:const Text('حفظ'))])));if(ok==true){try{final b={'name':name.text.trim(),'grade':grade.text.trim(),'subject':subject,'teacher_id':teacherId,'supervisor_id':supervisorId,'teacher_rate':double.parse(rate.text),'student_ids':selected.toList(),'status':'active'};if(item==null)await ApiService.post('groups',b);else await ApiService.put('groups/${id(item)}',b);await load();}catch(e){msg(e);}}for(final c in[name,grade,rate])c.dispose();}
Future<void> remove(dynamic g)async{final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('حذف المجموعة'),content:Text('حذف ${g['name']??''}؟'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('حذف'))]));if(ok==true){try{await ApiService.delete('groups/${id(g)}');await load();}catch(e){msg(e);}}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('المجموعات'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>form(),icon:const Icon(Icons.groups),label:const Text('إنشاء مجموعة')),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.fromLTRB(16,12,16,90),children:[...groups.map((g)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.groups)),title:Text('${g['name']??''}'),subtitle:Text('المدرس: ${g['teacher']?['name']??''}\nالمادة: ${g['subject']??''} • الطلاب: ${g['students_count']??0}'),isThreeLine:true,trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>form(item:g),icon:const Icon(Icons.edit)),IconButton(onPressed:()=>remove(g),icon:const Icon(Icons.delete))]))))])));}
